function normalizeBuiltin(w,i){
  return {
    id:"b_"+w.word.toLowerCase().replace(/[^a-z0-9]+/g,"_"),
    word:w.word, zh:w.zh, pos:w.pos||"", category:w.category||"核心字彙",
    star:w.star||4, score:w.score||"780-900", tier:w.tier||"825→900 核心缺口", forms:w.forms||[w.word],
    examples:[{english:w.example||"",chinese:w.exampleZh||""}],
    tips:w.tips||[w.collocation ? "常見搭配："+w.collocation : "熟悉詞性與常見搭配。"],
    collocation:w.collocation||""
  };
}
function normalizeSource(w){
  const ex=(Array.isArray(w.examples)?w.examples:[]).slice(0,2).map(x=>({english:String(x.english||""),chinese:String(x.chinese||"")}));
  const tips=(Array.isArray(w.exam_tips)?w.exam_tips:[]).slice(0,3).map(x=>String(x).slice(0,220));
  let forms=[];
  (Array.isArray(w.word_forms)?w.word_forms:[]).forEach(x=>(x.forms||[]).forEach(f=>forms.push(String(f))));
  forms=[String(w.english_word||""),...forms].filter(Boolean);
  return {
    id:"w_"+hash(String(w.english_word||"").toLowerCase()),
    word:String(w.english_word||"").trim(),
    zh:String(w.chinese_definition||"").trim(),
    pos:(Array.isArray(w.parts_of_speech)?w.parts_of_speech:[]).join(" / "),
    category:String(w.category||"一般專業"),
    star:Number(w.star_rating||0),
    score:String(w.toeic_score_range||""),
    tier:(String(w.toeic_score_range||"").trim()==="900+"
      ? "900+ 拉分字"
      : (String(w.toeic_score_range||"").trim()==="600-780" ? "高價值橋接" : "825→900 核心缺口")),
    forms:[...new Set(forms)],
    examples:ex,
    tips:tips.length?tips:["請連同詞性、搭配與商務情境一起記憶。"],
    collocation:""
  };
}
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(36)}
function seededShuffle(a,seed=9002026){a=[...a];let x=seed>>>0;for(let i=a.length-1;i>0;i--){x=(Math.imul(1664525,x)+1013904223)>>>0;let j=x%(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function select2000(raw){
  const valid=(raw||[]).filter(x=>x&&x.english_word&&x.chinese_definition);
  const byWord=new Map();
  for(const x of valid){
    const k=String(x.english_word||"").trim().toLowerCase();
    if(k&&!byWord.has(k)) byWord.set(k,x);
  }
  const selected=[];
  const missing=[];
  for(const target of MASTER_1200_WORDS){
    const x=byWord.get(target.toLowerCase());
    if(x) selected.push(normalizeSource(x));
    else missing.push(target);
  }
  lastFilterStats={
    source:valid.length,
    accepted:selected.length,
    rejectedScore:0,rejectedStars:0,rejectedBasic:0,rejectedRare:0,
    missing:missing.length
  };
  if(missing.length){
    console.warn("MASTER 1200 missing words:",missing);
    throw new Error(`固定字庫缺少 ${missing.length} 字：${missing.slice(0,8).join(", ")}`);
  }
  // 固定亂數：每次、每台裝置的 Part 01–24 都完全一致。
  return seededShuffle(selected,8259001200);
}
function pstate(id){
  if(!progress[id]) progress[id]={seen:0,level:0,correct:0,wrong:0,last:0,due:0,interval:0,fav:false};
  return progress[id];
}
function saveProgress(){try{localStorage.setItem(K_PROGRESS,JSON.stringify(progress))}catch(e){}}
function saveSettings(){try{localStorage.setItem(K_SETTINGS,JSON.stringify(settings))}catch(e){}}
function loadJSON(k,d){try{return JSON.parse(localStorage.getItem(k)||"null")||d}catch(e){return d}}
function now(){return Date.now()}
function rateWord(w,r){
  const p=pstate(w.id); p.seen++; p.last=now();
  if(r===0){p.wrong++;p.level=Math.max(0,p.level-1);p.interval=0.007}
  if(r===1){p.level=Math.max(1,p.level);p.interval=Math.max(1,p.interval||1)}
  if(r===2){p.correct++;p.level=Math.max(3,p.level);p.interval=Math.max(3,Math.round((p.interval||1)*1.8))}
  if(r===3){p.correct++;p.level=Math.min(5,Math.max(4,p.level+1));p.interval=Math.max(7,Math.round((p.interval||3)*2.2))}
  p.due=now()+p.interval*86400000; saveProgress();
}
function quizResult(w,ok){const p=pstate(w.id);p.seen++;p.last=now();if(ok){p.correct++;p.level=Math.min(5,Math.max(2,p.level+1));p.interval=Math.max(2,p.interval||2)}else{p.wrong++;p.level=Math.max(0,p.level-1);p.interval=.04}p.due=now()+p.interval*86400000;saveProgress()}
function markSeen(w){const p=pstate(w.id);if(!p.seen){p.seen=1;p.last=now();saveProgress()}}
function deckWords(n){return words.slice((n-1)*50,n*50)}
function deckCount(){return Math.ceil(words.length/50)}
