function tierShort(t){
  if(t==="900+ 拉分字")return "900+";
  if(t==="高價值橋接")return "橋接";
  return "核心";
}
function tierCounts(list=words){
  const o={"825→900 核心缺口":0,"900+ 拉分字":0,"高價值橋接":0};
  list.forEach(w=>{if(o[w.tier]!==undefined)o[w.tier]++});
  return o;
}
function priorityWords(list=words){
  const core=list.filter(w=>w.tier==="825→900 核心缺口");
  const bridge=list.filter(w=>w.tier==="高價值橋接");
  const stretch=list.filter(w=>w.tier==="900+ 拉分字");
  return [...shuffle(core),...shuffle(bridge),...shuffle(stretch)];
}
function filteredDeckWords(){
  let a=deckWords(currentDeck);
  if(activeTierFilter!=="all") a=a.filter(w=>w.tier===activeTierFilter);
  if(activeCategoryFilter!=="all") a=a.filter(w=>w.category===activeCategoryFilter);
  return a;
}
function resetDeckFilters(){activeTierFilter="all";activeCategoryFilter="all"}
function deckStats(n){
  const dw=deckWords(n);let seen=0, mastered=0;
  dw.forEach(w=>{const p=progress[w.id];if(p?.seen)seen++;if((p?.level||0)>=4)mastered++});
  return {seen,mastered,total:dw.length,pct:dw.length?Math.round(seen/dw.length*100):0};
}
function globalStats(){
  let seen=0,mastered=0,weak=0,due=0,fav=0;
  words.forEach(w=>{const p=progress[w.id];if(!p)return;if(p.seen)seen++;if(p.level>=4)mastered++;if(p.wrong>p.correct&&p.seen)weak++;if(p.due&&p.due<=now())due++;if(p.fav)fav++});
  return {seen,mastered,weak,due,fav};
}
