function speak(t){
  try{
    if(!("speechSynthesis" in window)) throw new Error("unsupported");
    speechSynthesis.cancel();
    const u=new SpeechSynthesisUtterance(String(t||""));
    const accent=settings.speechAccent==="gb"?"gb":"us";
    const lang=accent==="gb"?"en-GB":"en-US";
    u.lang=lang;
    u.rate=Number(settings.speechRate||.88);
    const voices=speechSynthesis.getVoices?.()||[];
    const localeRe=accent==="gb"?/^en[-_](GB|UK)$/i:/^en[-_]US$/i;
    const preferred=voices.find(v=>localeRe.test(String(v.lang||"")));
    // Only pin a voice when it really matches the requested accent.
    // Otherwise leave u.voice unset so the browser can resolve u.lang itself.
    if(preferred)u.voice=preferred;
    speechSynthesis.speak(u);
  }catch(e){toast("此瀏覽器無法朗讀")}
}
function toast(t){const el=document.getElementById("toast");el.textContent=t;el.classList.remove("hidden");clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.add("hidden"),2200)}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function attr(s){return esc(s)}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function seededLocalShuffle(a,seed){a=[...a];let x=seed||1;for(let i=a.length-1;i>0;i--){x=(x*9301+49297)%233280;let j=x%(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function chunk(a,n){let r=[];for(let i=0;i<a.length;i+=n)r.push(a.slice(i,i+n));return r}
function escapeRegExp(s){return String(s).replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}

function idbOpen(){return new Promise((res,rej)=>{try{const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE)};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)}catch(e){rej(e)}})}
async function idbGet(k){try{const db=await idbOpen();return await new Promise((res,rej)=>{const tx=db.transaction(STORE,"readonly"),r=tx.objectStore(STORE).get(k);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}catch(e){return null}}
async function idbSet(k,v){try{const db=await idbOpen();return await new Promise((res,rej)=>{const tx=db.transaction(STORE,"readwrite");tx.objectStore(STORE).put(v,k);tx.oncomplete=()=>res(true);tx.onerror=()=>rej(tx.error)})}catch(e){return false}}
async function idbDel(k){try{const db=await idbOpen();return await new Promise((res)=>{const tx=db.transaction(STORE,"readwrite");tx.objectStore(STORE).delete(k);tx.oncomplete=()=>res(true);tx.onerror=()=>res(false)})}catch(e){return false}}

async function loadFull(){
  const btns=[...document.querySelectorAll('[data-action="load-full"]')];btns.forEach(b=>{b.disabled=true;b.innerHTML='<span class="loader"></span> 載入中'});
  toast("正在載入固定 Master 1200…");
  let lastErr=null;
  for(const url of FULL_URLS){
    try{
      const r=await fetch(url,{cache:"no-store",mode:"cors"});
      if(!r.ok)throw new Error("HTTP "+r.status);
      const raw=await r.json();
      const selected=select2000(raw);
      words=selected;fullData=true;await idbSet(DATA_KEY,selected);toast("Master 1200 載入完成");show(currentScreen==="settings"?"settings":"home");return;
    }catch(e){lastErr=e}
  }
  btns.forEach(b=>{b.disabled=false;b.textContent="載入 Master 1200"});
  toast("下載被手機瀏覽器阻擋，可改用「匯入資料集 JSON」");
  if(currentScreen==="settings")renderSettings(); else renderHome();
}
